/* 3 rows from colour: 1 | No Colour ; 2 | Amber ; 3 | Auburn */
CREATE TABLE gender ( id INTEGER not null primary key, gender TEXT default NULL );
/* 3 rows from gender: 1 | Male ; 2 | Female ; 3 | N/A */
CREATE TABLE hero_attribute ( hero_id INTEGER default NULL, attribute_id INTEGER default NULL, attribute_value INTEGER default NULL, foreign key (attribute_id) references attribute(id), foreign key (hero_id) references superhero(id) );
/* 3 rows from hero_attribute: 1 | 1 | 80 ; 2 | 1 | 75 ; 3 | 1 | 95 */
CREATE TABLE hero_power ( hero_id INTEGER default NULL, power_id INTEGER default NULL, foreign key (hero_id) references superhero(id), foreign key (power_id) references superpower(id) );
/* 3 rows from hero_power: 1 | 1 ; 1 | 18 ; 1 | 26 */
CREATE TABLE publisher ( id INTEGER not null primary key, publisher_name TEXT default NULL );
/* 3 rows from publisher: 1 |  ; 2 | ABC Studios ; 3 | Dark Horse Comics */
CREATE TABLE race ( id INTEGER not null primary key, race TEXT default NULL );
/* 3 rows from race: 1 | - ; 2 | Alien ; 3 | Alpha */
CREATE TABLE superhero ( id INTEGER not null primary key, superhero_name TEXT default NULL, full_name TEXT default NULL, gender_id INTEGER default NULL, eye_colour_id INTEGER default NULL, hair_colour_id INTEGER default NULL, skin_colour_id INTEGER default NULL, race_id INTEGER default NULL, publisher_id INTEGER default NULL, alignment_id INTEGER default NULL, height_cm INTEGER default NULL, weight_kg INTEGER default NULL, foreign key (alignment_id) references alignment(id), foreign key (eye_colour_id) references colour(id), foreign key (gender_id) references gender(id), foreign key (hair_colour_id) references colour(id), foreign key (publisher_id) references publisher(id), foreign key (race_id) references race(id), foreign key (skin_colour_id) references colour(id) );
/* 3 rows from superhero: 1 | 3-D Man | Charles Chandler | 1 | 9 | 13 | 1 | 1 | 13 | 1 | 188 | 90 ; 2 | A-Bomb | Richard Milhouse Jones | 1 | 33 | 1 | 1 | 24 | 13 | 1 | 203 | 441 ; 3 | Abe Sapien | Abraham Sapien | 1 | 7 | 1 | 7 | 33 | 3 | 1 | 191 | 65 */
CREATE TABLE superpower ( id INTEGER not null primary key, power_name TEXT default NULL );
/* 3 rows from superpower: 1 | Agility ; 2 | Accelerated Healing ; 3 | Lantern Power Ring */

Question: How many percent of female heroes were published by Marvel Comics?
Evidence: percent = MULTIPLY(DIVIDE(SUM(gender = 'Female' WHERE publisher_name = 'Marvel Comics'), COUNT(publisher_name = 'Marvel Comics')), 100); female heroes refers to gender = 'Female'; Marvel Comics refers to publisher_name = 'Marvel Comics';

